import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    tokens = data[1:1+n]
    if not tokens or tokens[0] == 'null': print(''); sys.exit(0)
    class Node:
        def __init__(self, v): self.v = v; self.left = None; self.right = None
    root = Node(tokens[0])
    from collections import deque
    q = deque([root])
    idx = 1
    while q and idx < len(tokens):
        curr = q.popleft()
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.left = Node(tokens[idx]); q.append(curr.left)
        idx += 1
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.right = Node(tokens[idx]); q.append(curr.right)
        idx += 1
    def invert(node):
        if not node: return
        node.left, node.right = node.right, node.left
        invert(node.left); invert(node.right)
    invert(root)
    out = []
    q = deque([root])
    while q:
        curr = q.popleft()
        if curr:
            out.append(str(curr.v))
            q.append(curr.left); q.append(curr.right)
        else:
            out.append('null')
    while out and out[-1] == 'null': out.pop()
    print(' '.join(out))
else:
    print('')
